    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address other, uint256 v) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (v)); require(v <= 1000000000000000000000000000000);
        require(address(this).balance >= v, "insufficient balance");
        uint256 beforeCaller = c.balances(address(this)); if (__ESBMC_reverted()) return;
        c.Deposit{value: v}(); if (__ESBMC_reverted()) return;
        uint256 afterCaller = c.balances(address(this)); if (__ESBMC_reverted()) return;
        assert(afterCaller >= beforeCaller);
    }

    receive() external payable {
        c.Deposit{value: msg.value}(); if (__ESBMC_reverted()) return;
    }
}

