pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(address other, uint256 v) internal {
        v = bound(v, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= v);
        uint256 beforeCaller;
        try c.balances(address(this)) returns (uint256 __r) { beforeCaller = __r; } catch { return; }
        try c.Deposit{value: v}() {} catch { return; }
        uint256 afterCaller;
        try c.balances(address(this)) returns (uint256 __r) { afterCaller = __r; } catch { return; }
        assertTrue(afterCaller >= beforeCaller);
    }

    function testFuzz_run(address other, uint256 v) public {
        vm.assume(other.code.length == 0 && uint160(other) > 0xffff && other != address(this) && other != address(c) && other != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && other != 0x000000000000000000636F6e736F6c652e6c6f67 && other != 0x4e59b44847b379578588920cA78FbF26c0B4956C && other != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(other, v);
    }

    receive() external payable {
        try c.Deposit{value: msg.value}() {} catch { return; }
    }
}
